const producer = kafka.producer({
  // acks=-1 (all): Leader waits for all replicas in ISR to acknowledge disk write
  acks: -1,
  idempotent: true,
  maxRetries: 10,
  retry: {
    initialRetryTime: 100,
    factor: 2,
  }
});
// Requires broker topic setting: min.insync.replicas=2
